<script>
(function () {
  'use strict';

  var form = document.getElementById('signup');
  var success = document.getElementById('success');
  var toggle = document.getElementById('toggle-password');
  var submitted = false;

  // Pour chaque champ : normalisation de la saisie, puis validation.
  // validate() renvoie un message d'erreur, ou une chaîne vide si tout va bien.
  var rules = {
    name: {
      normalize: function (v) { return v.trim().replace(/\s+/g, ' '); },
      validate: function (v) {
        if (!v) return 'Saisissez votre nom complet.';
        if (v.length < 2 || !/\p{L}/u.test(v)) return 'Ce nom ne semble pas valide.';
        return '';
      }
    },

    email: {
      normalize: function (v) { return v.trim(); },
      validate: function (v) {
        if (!v) return 'Saisissez votre adresse e-mail.';
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v)) {
          return 'Saisissez une adresse e-mail valide, par exemple nom@exemple.fr.';
        }
        return '';
      }
    },

    website: {
      // « exemple.fr » devient « https://exemple.fr »
      normalize: function (v) {
        v = v.trim();
        if (v && !/^[a-z][a-z0-9+.-]*:\/\//i.test(v)) v = 'https://' + v;
        return v;
      },
      validate: function (v) {
        if (!v) return ''; // champ facultatif
        var invalid = 'Saisissez une adresse web valide, par exemple https://exemple.fr.';
        if (/\s/.test(v)) return invalid;
        var url;
        try { url = new URL(v); } catch (e) { return invalid; }
        if (url.protocol !== 'http:' && url.protocol !== 'https:') {
          return 'L\'adresse doit commencer par http:// ou https://.';
        }
        var host = url.hostname;
        if (url.username || url.password ||
            host.indexOf('.') < 1 || host.charAt(host.length - 1) === '.') {
          return invalid;
        }
        return '';
      }
    },

    password: {
      normalize: function (v) { return v; }, // on ne modifie jamais un mot de passe
      validate: function (v) {
        if (!v) return 'Saisissez un mot de passe.';
        if (v.length < 8) return 'Le mot de passe doit contenir au moins 8 caractères.';
        if (!/\p{L}/u.test(v) || !/\d/.test(v)) {
          return 'Le mot de passe doit contenir au moins une lettre et un chiffre.';
        }
        return '';
      }
    }
  };

  var names = Object.keys(rules);

  function showError(input, message) {
    var error = document.getElementById(input.id + '-error');
    error.textContent = message;
    if (message) {
      input.setAttribute('aria-invalid', 'true');
    } else {
      input.removeAttribute('aria-invalid');
    }
  }

  // Valide un champ ; si « commit » est vrai, la valeur normalisée
  // est réécrite dans le champ (à éviter pendant la frappe).
  function validateField(name, commit) {
    var input = form.elements[name];
    var value = rules[name].normalize(input.value);
    if (commit && value !== input.value) input.value = value;
    var message = rules[name].validate(value);
    showError(input, message);
    return !message;
  }

  names.forEach(function (name) {
    var input = form.elements[name];

    // À la sortie du champ : on valide s'il a été rempli
    // (ou si un envoi a déjà été tenté).
    input.addEventListener('blur', function () {
      if (submitted || input.value !== '') validateField(name, true);
    });

    // Pendant la frappe : on met à jour une erreur déjà affichée.
    input.addEventListener('input', function () {
      success.textContent = '';
      if (input.getAttribute('aria-invalid') === 'true') validateField(name, false);
    });
  });

  function setPasswordVisible(visible) {
    form.elements.password.type = visible ? 'text' : 'password';
    toggle.setAttribute('aria-pressed', String(visible));
    toggle.textContent = visible ? 'Masquer' : 'Afficher';
  }

  toggle.addEventListener('click', function () {
    setPasswordVisible(form.elements.password.type === 'password');
  });

  form.addEventListener('submit', function (event) {
    submitted = true;
    success.textContent = '';

    var firstInvalid = null;
    names.forEach(function (name) {
      if (!validateField(name, true) && !firstInvalid) {
        firstInvalid = form.elements[name];
      }
    });

    if (firstInvalid) {
      event.preventDefault();
      firstInvalid.focus();
      return;
    }

    // Formulaire valide : envoi réel si une « action » est définie.
    setPasswordVisible(false);
    if (form.hasAttribute('action')) return;

    // Sinon, mode démonstration.
    event.preventDefault();
    var fullName = form.elements.name.value;
    form.reset();
    submitted = false;
    success.textContent = 'Merci ' + fullName + ', votre inscription est validée.';
    success.focus();
  });
})();
</script>
